import catalog from '../../../data/theory/theories.json';

/**
 * Theories live in src/data/theory, isolated from the app's UI translations:
 * - theories.json: language-independent catalog (number, slug, topic);
 * - i18n/<lang>.json: page labels, topic names, titles and short versions;
 * - i18n/<lang>/NNN.json: the detailed version and sources of one theory.
 * Generated by tools/theory/import-theories.mjs from content/theories/*.md.
 */
export interface TheoryCatalogItem {
	n: number;
	slug: string;
	topic: string;
}

export interface TheoryTexts {
	ui: Record<string, string>;
	topics: Record<string, string>;
	theories: Record<string, { title: string; short: string }>;
}

export interface TheoryBody {
	sections: { title: string; text: string }[];
	sources: { label: string; url: string }[];
}

export const THEORY_TOPICS: string[] = catalog.topics;
export const THEORY_CATALOG: TheoryCatalogItem[] = catalog.theories;
export const FALLBACK_LANGUAGE = 'en';

export function theoryFileId(n: number): string {
	return String(n).padStart(3, '0');
}

/** Page labels, topics, titles and short versions in one language (English if it is missing). */
export async function loadTheoryTexts(language: string): Promise<TheoryTexts> {
	try {
		return (await import(`../../../data/theory/i18n/${language}.json`)).default as TheoryTexts;
	} catch {
		return (await import('../../../data/theory/i18n/en.json')).default as TheoryTexts;
	}
}

/** Detailed version of one theory in one language (English if it is missing). */
export async function loadTheoryBody(language: string, n: number): Promise<TheoryBody> {
	const id = theoryFileId(n);
	try {
		return (await import(`../../../data/theory/i18n/${language}/${id}.json`)).default as TheoryBody;
	} catch {
		return (await import(`../../../data/theory/i18n/en/${id}.json`)).default as TheoryBody;
	}
}

/** Fills `{name}` placeholders in a label. */
export function fillLabel(label: string, vars: Record<string, string | number>): string {
	return label.replace(/\{(\w+)\}/g, (match, key: string) =>
		key in vars ? String(vars[key]) : match,
	);
}
